# usage: agg.sh START END OUT [extra where]
S="avg(kills) kills_mu, stddevSamp(kills) kills_sd, avg(deaths) deaths_mu, stddevSamp(deaths) deaths_sd, avg(assists) assists_mu, stddevSamp(assists) assists_sd, avg(net_worth) net_worth_mu, stddevSamp(net_worth) net_worth_sd, avg(final_stats.player_damage) pd_mu, stddevSamp(final_stats.player_damage) pd_sd, avg(final_stats.boss_damage) bd_mu, stddevSamp(final_stats.boss_damage) bd_sd, avg(final_stats.teammate_healing) th_mu, stddevSamp(final_stats.teammate_healing) th_sd, avg(final_stats.player_healing) ph_mu, stddevSamp(final_stats.player_healing) ph_sd, avg(final_stats.self_healing) sh_mu, stddevSamp(final_stats.self_healing) sh_sd, avg(duration_s) dur_mu"
python3 scripts/dsql.py "SELECT hero_id, count() n, $S FROM match_player WHERE game_mode='Normal' AND match_mode IN ('Unranked','Ranked') AND start_time >= '$1' AND start_time < '$2' $4 GROUP BY hero_id ORDER BY hero_id" $3
